/**
 * Pure unit tests for OpportunityForecastService.weightedAmountByStage().
 *
 * No DML and no SOQL: the IOpportunitiesSelector dependency is mocked with ApexMocks and
 * registered through Application.Selector.setMock, and every Opportunity used as test data
 * is built in memory with fake Ids coming from fflib_IDGenerator.
 *
 * The tests pin down:
 *   - the weighted amount per StageName is Amount * Probability / 100, rounded to 2 decimals
 *     per opportunity, then summed per stage;
 *   - opportunities with a null Amount or a null Probability are ignored;
 *   - a null or empty set of account ids returns an empty map and never calls the selector.
 */
@IsTest
private class OpportunityForecastServiceTest {

    private static final String STAGE_QUALIFICATION = 'Qualification';
    private static final String STAGE_PROPOSAL = 'Proposal/Price Quote';

    @IsTest
    static void shouldSumWeightedAmountPerStage() {
        // Arrange
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(selectorMock);

        Id accountId = fflib_IDGenerator.getNextId(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId };

        List<Opportunity> openOpportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_QUALIFICATION, 1000, 25), // 250.00
            buildOpportunity(accountId, STAGE_QUALIFICATION, 2000, 10), // 200.00
            buildOpportunity(accountId, STAGE_PROPOSAL, 500, 50)        // 250.00
        };

        mocks.startStubbing();
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(openOpportunities);
        mocks.stopStubbing();

        // Act
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        // Assert
        System.assertNotEquals(null, result, 'A map must always be returned');
        System.assertEquals(2, result.size(), 'One entry per StageName carrying a weighted amount');
        assertDecimalEquals('450.00', result.get(STAGE_QUALIFICATION),
            'Qualification: 1000*25% + 2000*10% = 450.00');
        assertDecimalEquals('250.00', result.get(STAGE_PROPOSAL),
            'Proposal/Price Quote: 500*50% = 250.00');

        ((IOpportunitiesSelector) mocks.verify(selectorMock, 1)).selectOpenByAccountIds(accountIds);
    }

    @IsTest
    static void shouldRoundEachOpportunityToTwoDecimalsBeforeSumming() {
        // Arrange
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(selectorMock);

        Id accountId = fflib_IDGenerator.getNextId(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId };

        // Each opportunity: 10.004 * 100 / 100 = 10.004, which must be rounded to 10.00
        // per opportunity. Rounding only the grand total would give 20.01 instead of 20.00.
        List<Opportunity> openOpportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_QUALIFICATION, 10.004, 100),
            buildOpportunity(accountId, STAGE_QUALIFICATION, 10.004, 100)
        };

        mocks.startStubbing();
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(openOpportunities);
        mocks.stopStubbing();

        // Act
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        // Assert
        System.assertEquals(1, result.size(), 'All opportunities share the same StageName');
        assertDecimalEquals('20.00', result.get(STAGE_QUALIFICATION),
            'Each opportunity must be rounded to 2 decimals before being summed');
    }

    @IsTest
    static void shouldIgnoreOpportunitiesWithMissingAmountOrProbability() {
        // Arrange
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(selectorMock);

        Id accountId = fflib_IDGenerator.getNextId(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId };

        List<Opportunity> openOpportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_QUALIFICATION, 1000, 50),   // 500.00
            buildOpportunity(accountId, STAGE_QUALIFICATION, null, 50),   // no Amount
            buildOpportunity(accountId, STAGE_QUALIFICATION, 1000, null), // no Probability
            buildOpportunity(accountId, STAGE_PROPOSAL, null, null)       // nothing usable
        };

        mocks.startStubbing();
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(openOpportunities);
        mocks.stopStubbing();

        // Act
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        // Assert
        System.assertEquals(1, result.size(), 'Only stages with a usable weighted amount are returned');
        assertDecimalEquals('500.00', result.get(STAGE_QUALIFICATION),
            'Only the opportunity carrying both Amount and Probability contributes');
        System.assert(!result.containsKey(STAGE_PROPOSAL),
            'A stage whose opportunities are all incomplete must not appear in the result');
    }

    @IsTest
    static void shouldReturnEmptyMapWithoutCallingSelectorWhenAccountIdsIsNull() {
        // Arrange
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(selectorMock);

        // Act
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(null);

        // Assert
        System.assertNotEquals(null, result, 'A map must always be returned');
        System.assert(result.isEmpty(), 'A null set of account ids must return an empty map');

        ((IOpportunitiesSelector) mocks.verify(selectorMock, 0)).selectOpenByAccountIds((Set<Id>) null);
    }

    @IsTest
    static void shouldReturnEmptyMapWithoutCallingSelectorWhenAccountIdsIsEmpty() {
        // Arrange
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(selectorMock);

        Set<Id> accountIds = new Set<Id>();

        // Act
        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        // Assert
        System.assertNotEquals(null, result, 'A map must always be returned');
        System.assert(result.isEmpty(), 'An empty set of account ids must return an empty map');

        ((IOpportunitiesSelector) mocks.verify(selectorMock, 0)).selectOpenByAccountIds(accountIds);
    }

    /**
     * Builds an in-memory Opportunity carrying a fake Id - no DML is involved.
     */
    private static Opportunity buildOpportunity(
        Id accountId,
        String stageName,
        Decimal amount,
        Integer probability
    ) {
        return new Opportunity(
            Id = fflib_IDGenerator.getNextId(Opportunity.SObjectType),
            AccountId = accountId,
            Name = 'Test Opportunity',
            StageName = stageName,
            Amount = amount,
            Probability = probability,
            CloseDate = Date.today().addDays(30)
        );
    }

    /**
     * Decimal scale-insensitive assertion: the service may return a value with a different
     * scale than the literal used here, only the numeric value matters.
     */
    private static void assertDecimalEquals(String expected, Decimal actual, String message) {
        System.assertNotEquals(null, actual, message);
        System.assertEquals(0, Decimal.valueOf(expected).compareTo(actual), message);
    }
}
