/**
 * Pure unit tests for OpportunityCleanupService.closeStale.
 *
 * No DML and no SOQL: the selector and the unit of work are mocked with
 * ApexMocks and injected through Application.Selector / Application.UnitOfWork.
 * Fake ids come from fflib_IDGenerator.
 */
@IsTest
private class OpportunityCleanupServiceTest {

    private static final Date CUTOFF = Date.newInstance(2024, 6, 1);
    private static final String OPPORTUNITY_KEY_PREFIX = Opportunity.SObjectType.getDescribe().getKeyPrefix();

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static Opportunity buildOpportunity(
        String name,
        String stageName,
        Date closeDate,
        Integer idSuffix
    ) {
        return new Opportunity(
            Id = (Id) (OPPORTUNITY_KEY_PREFIX + String.valueOf(idSuffix).leftPad(12, '0')),
            Name = name,
            StageName = stageName,
            CloseDate = closeDate
        );
    }

    private static Set<Id> idsOf(List<Opportunity> opportunities) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity opp : opportunities) {
            ids.add(opp.Id);
        }
        return ids;
    }

    // ------------------------------------------------------------------
    // Guard clauses: null / empty ids
    // ------------------------------------------------------------------

    @IsTest
    static void returnsZeroAndDoesNothingWhenIdsAreNull() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        Integer result = OpportunityCleanupService.closeStale(null, CUTOFF);
        Test.stopTest();

        System.assertEquals(0, result, 'Null ids must close nothing');
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty((SObject) fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    @IsTest
    static void returnsZeroAndDoesNothingWhenIdsAreEmpty() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        Integer result = OpportunityCleanupService.closeStale(new Set<Id>(), CUTOFF);
        Test.stopTest();

        System.assertEquals(0, result, 'Empty ids must close nothing');
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty((SObject) fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).commitWork();
    }

    // ------------------------------------------------------------------
    // Boundary rules
    // ------------------------------------------------------------------

    @IsTest
    static void closesOnlyStaleOpportunitiesAndCommitsOnce() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Opportunity staleOpen = buildOpportunity('Stale open', 'Prospecting', CUTOFF.addDays(-1), 1);
        staleOpen.Description = 'original description 1';

        Opportunity staleNegotiating = buildOpportunity('Stale negotiating', 'Negotiation/Review', CUTOFF.addDays(-30), 2);
        staleNegotiating.Description = 'original description 2';

        // Closes exactly on the cutoff -> "strictly before" is required, so it must be left alone
        Opportunity closesOnCutoff = buildOpportunity('Closes on cutoff', 'Prospecting', CUTOFF, 3);
        closesOnCutoff.Description = 'keep cutoff';

        // Closes after the cutoff -> left alone
        Opportunity closesAfterCutoff = buildOpportunity('Closes after cutoff', 'Prospecting', CUTOFF.addDays(1), 4);
        closesAfterCutoff.Description = 'keep after';

        // No close date -> left alone
        Opportunity noCloseDate = buildOpportunity('No close date', 'Prospecting', null, 5);
        noCloseDate.Description = 'keep null date';

        // Already closed -> left alone
        Opportunity alreadyWon = buildOpportunity('Already won', 'Closed Won', CUTOFF.addDays(-10), 6);
        alreadyWon.Description = 'keep won';

        Opportunity alreadyLost = buildOpportunity('Already lost', 'Closed Lost', CUTOFF.addDays(-10), 7);
        alreadyLost.Description = 'keep lost';

        List<Opportunity> selected = new List<Opportunity>{
            staleOpen, staleNegotiating, closesOnCutoff, closesAfterCutoff, noCloseDate, alreadyWon, alreadyLost
        };
        Set<Id> ids = idsOf(selected);

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(selected);
        mocks.stopStubbing();

        Test.startTest();
        Integer result = OpportunityCleanupService.closeStale(ids, CUTOFF);
        Test.stopTest();

        // Return value equals the number of opportunities actually closed
        System.assertEquals(2, result, 'Exactly the two stale opportunities must be closed');

        // Stale opportunities get the new stage and the lost reason
        System.assertEquals('Closed Lost', staleOpen.StageName, 'Stale open must be closed lost');
        System.assertEquals(OpportunityCleanupService.LOST_REASON, staleOpen.Description, 'Stale open must get the lost reason');
        System.assertEquals('Closed Lost', staleNegotiating.StageName, 'Stale negotiating must be closed lost');
        System.assertEquals(OpportunityCleanupService.LOST_REASON, staleNegotiating.Description, 'Stale negotiating must get the lost reason');

        // Everything else is untouched
        System.assertEquals('Prospecting', closesOnCutoff.StageName, 'Closing exactly on the cutoff is not stale');
        System.assertEquals('keep cutoff', closesOnCutoff.Description, 'Closing exactly on the cutoff must not be touched');
        System.assertEquals('Prospecting', closesAfterCutoff.StageName, 'Closing after the cutoff is not stale');
        System.assertEquals('keep after', closesAfterCutoff.Description, 'Closing after the cutoff must not be touched');
        System.assertEquals('Prospecting', noCloseDate.StageName, 'A null close date is not stale');
        System.assertEquals('keep null date', noCloseDate.Description, 'A null close date must not be touched');
        System.assertEquals('Closed Won', alreadyWon.StageName, 'Closed Won is not stale');
