public with sharing class Opportunities extends fflib_SObjectDomain
{
    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities((List<Opportunity>) sObjectList);
        }
    }

    /**
     * Before insert hook. Delegates to the map based hook using the old records when this is
     * an update (so the "already won" rule can see the previous stage) or an empty map on insert.
     */
    public override void onValidate()
    {
        onValidate(Trigger.isUpdate ? Trigger.oldMap : new Map<Id, SObject>());
    }

    /**
     * Before update hook (and the shared implementation used by before insert).
     */
    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        for (Opportunity opp : (List<Opportunity>) Records)
        {
            // Rule 1: Amount must never be negative (insert and update)
            if (opp.Amount != null && opp.Amount < 0)
            {
                fail(opp, 'Amount cannot be negative.');
            }

            // Rule 2: an opportunity that was already Closed Won before the update
            // cannot have its Amount changed.
            Opportunity existing = (Opportunity) existingRecords.get(opp.Id);
            if (existing != null
                && existing.StageName == 'Closed Won'
                && opp.Amount != existing.Amount)
            {
                fail(opp, 'Amount cannot change on a won opportunity.');
            }
        }
    }

    /**
     * Records the error through fflib (for unit tests inspecting fflib_SObjectDomain.Errors)
     * and also puts it on the Amount field of the offending record so the DML actually fails.
     */
    private void fail(Opportunity opp, String message)
    {
        error(message, opp, Opportunity.Amount);
        opp.addError(Opportunity.Amount, message);
    }
}
