        return (List<Opportunity>) selectSObjectsById(opportunityIds);
    }

    /**
     * Returns the open opportunities of the given accounts, highest Amount first,
     * opportunities without an Amount after all the others, ties broken by the
     * earliest CloseDate. At most maxRecords rows are returned in a single query.
     *
     * The query is built from the selector's query factory so the selector's field
     * list and security settings keep applying. The factory's default sort order
     * (opportunity Name, used by the selector's other methods) is replaced by the
     * ordering required here.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = newQueryFactory();
        queryFactory.selectField('Account.Name');
        queryFactory.setCondition('IsClosed = false AND AccountId IN :accountIds');

        String soql = queryFactory.toSOQL();
        Integer orderByIndex = soql.indexOf(' ORDER BY');
        if (orderByIndex > -1) {
            soql = soql.substring(0, orderByIndex);
        }
        soql += ' ORDER BY Amount DESC NULLS LAST, CloseDate ASC LIMIT ' + maxRecords;

        return (List<Opportunity>) Database.query(soql);
    }
}
