/**
 * Selector for the Account SObject used by the credit team.
 *
 * Field set fields:
 *   The field set fields are added by fflib_SObjectSelector because the selector is
 *   constructed with includeFieldSetFields = true, and fflib_SObjectSelector adds the
 *   fields of every field set on Account (today Credit_Review: AnnualRevenue, Rating).
 *   Admins can add or remove fields on the field set without any code change.
 *
 * Data access:
 *   Every query runs in user mode (WITH USER_MODE). The data access setting is set on
 *   the selector itself, so the platform enforces the running user's object, field and
 *   sharing access: a user who cannot read one of the selected fields (for example a
 *   field of the Credit_Review field set) gets an exception instead of data.
 */
public inherited sharing class AccountsSelector extends fflib_SObjectSelector
{
    public AccountsSelector()
    {
        // includeFieldSetFields = true  -> add the fields of the Account field sets (Credit_Review)
        // enforceCRUD          = false -> the platform enforces object access (user mode)
        // enforceFLS           = false -> the platform enforces field access (user mode)
        // sortSelectFields     = true
        super(true, false, false, true);

        // Run every query of this selector in user mode so the platform
        // enforces the running user's object, field and sharing access.
        this.setDataAccess(fflib_SObjectSelector.DataAccess.USER_MODE);
    }

    public Schema.SObjectType getSObjectType()
    {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList()
    {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    /**
     * Selects the accounts with the given ids.
     */
    public List<Account> selectById(Set<Id> accountIds)
    {
        fflib_QueryFactory accountsQueryFactory = newQueryFactory();
        accountsQueryFactory.setCondition('Id IN :accountIds');

        return (List<Account>) Database.query(accountsQueryFactory.toSOQL());
    }

    /**
     * Selects the accounts with the given ids and their Contacts in the same query.
     * The Contacts subquery is built from the ContactsSelector field list, so both
     * selectors always select the same contact fields.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds)
    {
        fflib_QueryFactory accountsQueryFactory = newQueryFactory();
        accountsQueryFactory.setCondition('Id IN :accountIds');

        fflib_QueryFactory contactsQueryFactory = accountsQueryFactory.subselectQuery('Contacts');
        for (Schema.SObjectField contactField : new ContactsSelector().getSObjectFieldList())
        {
            contactsQueryFactory.selectField(contactField);
        }

        return (List<Account>) Database.query(accountsQueryFactory.toSOQL());
    }
}
