/**
 * EmployerService
 *
 * Keeps NPSP Affiliations in sync with the employer a donor supplies on the web form.
 *
 * Post-conditions for every Contact / Organization pair passed in:
 *   - a Current, Primary npe5__Affiliation__c exists between the Contact and the Organization;
 *   - Contact.npsp__Primary_Affiliation__c points at that Organization;
 *   - a previous primary employer is left behind by NPSP as a Former, non-primary Affiliation
 *     with an End Date of today - we only declare the new primary Affiliation and let NPSP's
 *     standard Affiliation logic do the demotion, so we never write the end date ourselves;
 *   - the Contact is never moved out of its Household Account (Contact.AccountId is untouched).
 *
 * Bulk safe: 2 SOQL queries and 2 DML statements of our own, no matter how many Contacts arrive.
 * The Affiliation record is the source of truth, so an Affiliation that already exists for the
 * employer is promoted instead of duplicated.
 *
 * The class runs in system mode for its DML (AccessLevel.SYSTEM_MODE) because the caller is a
 * public web form / community context whose running user is not guaranteed field access to the
 * NPSP Affiliation fields. It stays `with sharing` for record visibility.
 */
public with sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        Set<Id> employerIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);
            if (contactId != null && employerId != null) {
                contactIds.add(contactId);
                employerIds.add(employerId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // -------------------------------------------------------------------
        // Query 1 of 2 - the Contacts. Confirms the Ids are real (so a bad key
        // cannot blow up the whole transaction) and gives us the current
        // Primary Affiliation lookup.
        // -------------------------------------------------------------------
        Map<Id, Contact> contactsById = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        // -------------------------------------------------------------------
        // Query 2 of 2 - the Affiliations that already exist between these
        // Contacts and the incoming Organizations, so we can promote one
        // instead of creating a duplicate.
        // -------------------------------------------------------------------
        Map<Id, npe5__Affiliation__c> existingByContactId = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c affiliation : [
                SELECT Id,
                       npe5__Contact__c,
                       npe5__Organization__c,
                       npe5__Status__c,
                       npe5__Primary__c
                FROM npe5__Affiliation__c
                WHERE npe5__Contact__c IN :contactIds
                  AND npe5__Organization__c IN :employerIds]) {

            npe5__Affiliation__c alreadyFound = existingByContactId.get(affiliation.npe5__Contact__c);
            // Prefer a Current affiliation, then a Primary one; ignore anything else if we
            // already have something usable for that Contact.
            Boolean keepIt = (alreadyFound == null)
                || (affiliation.npe5__Status__c == STATUS_CURRENT && alreadyFound.npe5__Status__c != STATUS_CURRENT)
                || (affiliation.npe5__Primary__c == true && alreadyFound.npe5__Primary__c != true);
            if (keepIt) {
                existingByContactId.put(affiliation.npe5__Contact__c, affiliation);
            }
        }

        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {

            Contact contact = contactsById.get(contactId);
            if (contact == null) {
                continue; // unknown or inaccessible Contact - skip it
            }

            Id employerId = employerByContactId.get(contactId);

            // The Organization already is this Contact's primary affiliation:
            // leave everything exactly as it is, do not create a duplicate.
            if (contact.npsp__Primary_Affiliation__c == employerId) {
                continue;
            }

            npe5__Affiliation__c existing = existingByContactId.get(contactId);
            if (existing != null && existing.npe5__Primary__c == true
                    && existing.npe5__Organization__c == employerId) {
                // Already the primary Affiliation for this employer, just a stale Contact
                // lookup - leave the Affiliation alone.
                continue;
            }

            if (existing != null) {
                // Promote the Affiliation that already exists for this employer. NPSP's
                // Affiliation logic demotes the old primary employer to Former for us.
                existing.npe5__Status__c  = STATUS_CURRENT;
                existing.npe5__Primary__c = true;
                affiliationsToUpdate.add(existing);
            } else {
                // Declaring a new primary Affiliation is NPSP's standard mechanism: it
                // keeps Contact.npsp__Primary_Affiliation__c in sync and retires the
                // previous primary employer as a Former, non-primary Affiliation with
                // today's end date.
                affiliationsToInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c      = contactId,
                    npe5__Organization__c = employerId,
                    npe5__Status__c       = STATUS_CURRENT,
                    npe5__Primary__c      = true
                ));
            }
        }

        // DML 1 of 2 - promote the Affiliations that already existed.
        if (!affiliationsToUpdate.isEmpty()) {
            Database.update(affiliationsToUpdate, AccessLevel.SYSTEM_MODE);
        }

        // DML 2 of 2 - create the new primary Affiliations.
        if (!affiliationsToInsert.isEmpty()) {
            Database.insert(affiliationsToInsert, AccessLevel.SYSTEM_MODE);
        }
    }
}
