public with sharing class HouseholdService {

    // DeveloperName of the NPSP Household Account record type. Resolved at
    // runtime so no record type Id is ever hard-coded.
    private static final String HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';

    // Account.Name is a required field at the object level, so a value must be
    // supplied at insert time. This is only a throwaway placeholder: NPSP's
    // automatic household naming immediately replaces it once the members are
    // attached, so we never compute the real household name ourselves.
    private static final String PLACEHOLDER_HOUSEHOLD_NAME = 'Household';

    /**
     * Creates one new NPSP household account for the supplied (new) contacts,
     * links every contact to that single household, makes the first contact the
     * household's primary contact, and returns the household account Id.
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('At least one household member is required.');
        }

        Id householdRecordTypeId = getHouseholdRecordTypeId();

        // 1. Create the household. It is a real NPSP household (HH_Account
        //    record type), so NPSP owns the naming/greeting logic.
        Account household = new Account(
            RecordTypeId = householdRecordTypeId,
            Name = PLACEHOLDER_HOUSEHOLD_NAME
        );
        insert household;

        // 2. Attach every member to the one new household before inserting them,
        //    so NPSP sees a single populated household instead of creating any
        //    extra/empty ones.
        for (Contact member : members) {
            member.AccountId = household.Id;
        }
        insert members;

        // 3. Make the first member the household's primary contact. NPSP's
        //    naming service reads this to (re)generate the household name and
        //    greetings.
        //
        //    IMPORTANT: send only Id + the primary contact. Reusing the
        //    'household' instance from step 1 would write its stale
        //    placeholder Name back over the name NPSP just generated.
        Account householdUpdate = new Account(
            Id = household.Id,
            npe01__One2OneContact__c = members[0].Id
        );
        update householdUpdate;

        return household.Id;
    }

    /**
     * Returns the Id of the NPSP Household Account record type by DeveloperName.
     */
    private static Id getHouseholdRecordTypeId() {
        RecordTypeInfo householdRecordType =
            Schema.SObjectType.Account.getRecordTypeInfosByDeveloperName()
                .get(HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME);

        if (householdRecordType == null) {
            throw new IllegalArgumentException(
                'The Household Account record type (' +
                HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME + ') is not available in this org.'
            );
        }

        return householdRecordType.getRecordTypeId();
    }
}
