```apex
/**
 * TDTM trigger handler that creates a follow-up Task whenever an Opportunity
 * becomes a "major gift" (Closed Won with Amount >= 5000).
 *
 * Registered by the admin through an NPSP Trigger Handler record:
 *   Class            : OPP_MajorGiftFollowUp_TDTM
 *   Object           : Opportunity
 *   Trigger Action   : AfterInsert;AfterUpdate
 *   Load Order       : 5
 *   Asynchronous     : false
 *
 * There is deliberately no Apex trigger on Opportunity - NPSP's Table-Driven
 * Trigger Management dispatcher invokes this class, so deactivating the Trigger
 * Handler record stops the automation.
 *
 * The handler is bulk safe: any number of Opportunities (e.g. 200) are handled
 * with at most one SOQL query and one DML statement of its own.
 */
global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final String TASK_PRIORITY = 'High';
    private static final String TASK_STATUS = 'Not Started';
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final Integer FOLLOW_UP_OFFSET_DAYS = 3;

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Boolean isAfterInsert = triggerAction == npsp.TDTM_Runnable.Action.AfterInsert;
        Boolean isAfterUpdate = triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate;

        // This handler is only registered for AfterInsert / AfterUpdate, but
        // guard anyway so it is safe if the registration is ever changed.
        if (!isAfterInsert && !isAfterUpdate) {
            return dmlWrapper;
        }

        // Build the "old" map only when we actually need it (updates).
        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (isAfterUpdate && oldlist != null) {
            for (SObject oldRecord : oldlist) {
                if (oldRecord != null && oldRecord.Id != null) {
                    oldOppsById.put(oldRecord.Id, (Opportunity)oldRecord);
                }
            }
        }

        // Determine which Opportunities newly qualify as major gifts.
        Map<Id, Opportunity> qualifyingOpps = new Map<Id, Opportunity>();
        for (SObject newRecord : newlist) {
            if (newRecord == null) {
                continue;
            }

            Opportunity opp = (Opportunity)newRecord;

            if (!isMajorGift(opp)) {
                continue;
            }

            // On update only act when the record was not already a major gift.
            if (isAfterUpdate) {
                Opportunity oldOpp = oldOppsById.get(opp.Id);
                if (oldOpp != null && isMajorGift(oldOpp)) {
                    continue;
                }
            }

            qualifyingOpps.put(opp.Id, opp);
        }

        if (qualifyingOpps.isEmpty()) {
            return dmlWrapper;
        }

        // Single SOQL query: skip Opportunities that already have a follow-up
        // task so re-qualifying a gift never produces a duplicate.
        Set<Id> oppsWithExistingTask = new Set<Id>();
        for (Task existingTask : [
            SELECT WhatId
            FROM Task
            WHERE WhatId IN :qualifyingOpps.keySet()
            AND Subject = :TASK_SUBJECT
        ]) {
            oppsWithExistingTask.add(existingTask.WhatId);
        }

        // Build the follow-up tasks.
        List<Task> tasksToInsert = new List<Task>();
        for (Opportunity opp : qualifyingOpps.values()) {
            if (oppsWithExistingTask.contains(opp.Id)) {
                continue;
            }
            tasksToInsert.add(buildFollowUpTask(opp));
        }

        // Hand the tasks back through TDTM's DmlWrapper - this is the single DML
        // statement for the transaction and lets NPSP persist them in bulk.
        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        }

        return dmlWrapper;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Task followUp = new Task();
        followUp.Subject = TASK_SUBJECT;
        followUp.Priority = TASK_PRIORITY;
        followUp.Status = TASK_STATUS;
        followUp.WhatId = opp.Id;
        followUp.WhoId = opp.npsp__Primary_Contact__c; // may be null
        followUp.OwnerId = opp.OwnerId;
        if (opp.CloseDate != null) {
            followUp.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_OFFSET_DAYS);
        }
        return followUp;
    }

    private static Boolean isMajorGift(Opportunity opp) {
        return opp != null
            && opp.StageName == STAGE_CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }
}
